package br.com.tapeteskalke.service;
import br.com.tapeteskalke.dto.OperacaoDtos.*; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.security.CurrentUser; import java.math.*; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProducaoService { private final OrdemProducaoRepository ordens; private final ProdutoService produtos; private final ClienteService clientes; private final FornecedorRepository fornecedores; private final EstoqueService estoque; private final PermissionService permissions; private final CurrentUser current; private final NumeroService numeros; private final Clock clock; public ProducaoService(OrdemProducaoRepository ordens,ProdutoService produtos,ClienteService clientes,FornecedorRepository fornecedores,EstoqueService estoque,PermissionService permissions,CurrentUser current,NumeroService numeros,Clock clock){this.ordens=ordens;this.produtos=produtos;this.clientes=clientes;this.fornecedores=fornecedores;this.estoque=estoque;this.permissions=permissions;this.current=current;this.numeros=numeros;this.clock=clock;}
 @Transactional public OrdemResponse create(OrdemRequest r){permissions.action("producao_criar");if("ENCOMENDA".equals(r.tipoOrdem())&&(r.clienteId()==null||r.clienteId().isBlank()))throw new BusinessException("CLIENTE_OBRIGATORIO","Encomenda exige cliente",HttpStatus.UNPROCESSABLE_ENTITY);var o=new OrdemProducao();o.setNumeroOrdem(numeros.nextOrdem());o.setProdutoAcabado(produtos.active(r.produtoAcabadoId()));o.setQuantidadeProduzida(r.quantidadeProduzida());o.setTipoOrdem(r.tipoOrdem());o.setCliente(r.clienteId()==null||r.clienteId().isBlank()?null:clientes.active(r.clienteId()));o.setFornecedor(r.fornecedorId()==null||r.fornecedorId().isBlank()?null:fornecedores.findById(r.fornecedorId()).orElseThrow(()->new ResourceNotFoundException("Fornecedor",r.fornecedorId())));o.setDataOrdem(LocalDate.now(clock));o.setObservacoes(r.observacoes());o.setCreatedBy(current.require().id());o.setUpdatedBy(current.require().id());for(var input:r.materiasPrimas()){if(input.produtoId().equals(r.produtoAcabadoId()))throw new BusinessException("MATERIA_PRIMA_IGUAL_PRODUTO","O produto acabado não pode ser matéria-prima da própria ordem",HttpStatus.UNPROCESSABLE_ENTITY);var p=produtos.active(input.produtoId());if(!p.isPodeSerMateriaPrima())throw new BusinessException("PRODUTO_NAO_E_MATERIA_PRIMA",p.getNome()+" não pode ser matéria-prima",HttpStatus.UNPROCESSABLE_ENTITY);var item=new OrdemProducaoItem();item.setProdutoMateriaPrima(p);item.setQuantidadeUsada(input.quantidadeUsada());item.setProdutoNomeSnapshot(p.getNome());item.setUnidadeSnapshot(p.getUnidadeMedida());o.addItem(item);}ordens.save(o);return response(o);}
 @Transactional public OrdemResponse finish(String id){permissions.action("producao_finalizar");var o=ordens.detail(id).orElseThrow(()->new ResourceNotFoundException("Ordem de produção",id));if(!"ABERTA".equals(o.getStatus()))throw new BusinessException("ORDEM_NAO_FINALIZAVEL","Ordem não está aberta",HttpStatus.CONFLICT);var ids=new TreeSet<String>();ids.add(o.getProdutoAcabado().getId());o.getMateriasPrimas().forEach(i->ids.add(i.getProdutoMateriaPrima().getId()));Map<String,Produto> locked=new HashMap<>();for(var productId:ids)locked.put(productId,produtos.locked(productId));for(var i:o.getMateriasPrimas()){var p=locked.get(i.getProdutoMateriaPrima().getId());estoque.change(p,"PRODUCAO",i.getQuantidadeUsada().negate(),"CONSUMO_PRODUCAO","PRODUCAO",o.getId(),"Ordem "+o.getNumeroOrdem());}var finished=locked.get(o.getProdutoAcabado().getId());estoque.change(finished,"COMERCIAL",o.getQuantidadeProduzida(),"ENTRADA_PRODUCAO","PRODUCAO",o.getId(),"Ordem "+o.getNumeroOrdem());o.setStatus("FINALIZADA");o.setDataFinalizacao(OffsetDateTime.now(clock));o.setIdUsuarioFinalizacao(current.require().id());o.setUpdatedBy(current.require().id());return response(o);} // Ordem aberta ainda não movimentou estoque, então cancelar não gera estorno.
 @Transactional public OrdemResponse cancel(String id,CancelarRequest r){permissions.action("producao_cancelar");var o=ordens.detail(id).orElseThrow(()->new ResourceNotFoundException("Ordem de produção",id));if(!"ABERTA".equals(o.getStatus()))throw new BusinessException("ORDEM_NAO_CANCELAVEL","Somente ordens abertas podem ser canceladas",HttpStatus.CONFLICT);o.setStatus("CANCELADA");var nota="Cancelada: "+r.motivo();o.setObservacoes(o.getObservacoes()==null||o.getObservacoes().isBlank()?nota:o.getObservacoes()+"\n"+nota);o.setUpdatedBy(current.require().id());return response(o);}
 @Transactional(readOnly=true) public List<OrdemResponse> list(){return ordens.listWithProduct().stream().map(this::response).toList();} private OrdemResponse response(OrdemProducao o){return new OrdemResponse(o.getId(),o.getNumeroOrdem(),o.getProdutoAcabado().getNome(),o.getQuantidadeProduzida(),o.getStatus(),o.getDataOrdem());}
}